  return (
    <View style={styles.s}>
      <Text nativeID="mode" style={styles.mode}>{wide ? "Өргөн дэлгэц" : "Нарийн дэлгэц"}</Text>
    </View>
  );
}

const styles = StyleSheet.create({ s: { flex: 1, alignItems: "center", justifyContent: "center" }, mode: { fontSize: 20, fontWeight: "bold" } });

registerRootComponent(App);
